import{_ as t,o as n,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const f=JSON.parse('{"title":"ADR-0015 — Sans fournisseur de captcha configuré, la soumission publique est refusée","description":"Extrait de docs/adr/0015-captcha-non-configure-refus-de-soumission.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0015 — Sans fournisseur de captcha configuré, la soumission publique est refusée","description":"Extrait de docs/adr/0015-captcha-non-configure-refus-de-soumission.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0015-captcha-non-configure-refus-de-soumission.md","filePath":"developpeurs/adr/0015-captcha-non-configure-refus-de-soumission.md"}'),a={name:"developpeurs/adr/0015-captcha-non-configure-refus-de-soumission.md"};function s(o,e,u,c,l,d){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0015--sans-fournisseur-de-captcha-configuré-la-soumission-publique-est-refusée" tabindex="-1">ADR-0015 — Sans fournisseur de captcha configuré, la soumission publique est refusée <a class="header-anchor" href="#adr-0015--sans-fournisseur-de-captcha-configuré-la-soumission-publique-est-refusée" aria-label="Permalink to &quot;ADR-0015 — Sans fournisseur de captcha configuré, la soumission publique est refusée {#adr-0015--sans-fournisseur-de-captcha-configuré-la-soumission-publique-est-refusée}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté avec garde-fou — <strong>décision n°1 amendée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a></strong> (14 septembre 2026, décision n°2 de l&#39;ADR-0027 : trois vérificateurs de captcha — Turnstile, hCaptcha, Altcha — sont désormais livrés avec le Core, inactifs tant que <code>CAPTCHA_PROVIDER</code> et <code>CAPTCHA_SECRET_KEY</code> ne sont pas réglés ; le refus sans fournisseur configuré est inchangé) <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §7.1 (captcha), §8.3 (pas de fuite par défaut), §14.11 (le CMS fonctionne sans configuration IA) ; corpus Les MogWais — « captcha sur tous les formulaires publics, sans exception » <strong>Renvois ultérieurs :</strong> complétée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0036-captcha-sans-consentement-repli-altcha">ADR-0036</a> (19 septembre 2026 : repli Altcha proposé d&#39;office au visiteur qui n&#39;a pas consenti au captcha tiers)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>La soumission d&#39;un formulaire public est le <strong>premier chemin d&#39;écriture non authentifié de tout le CMS</strong>. Avant l&#39;Epic E11, tous les routeurs (<code>auth</code>, <code>staff_users</code>, <code>access</code>, <code>lifecycle</code>, <code>pages</code>, <code>content_types</code>, <code>plugins</code>, <code>cookies</code>, <code>rgpd</code>, <code>listings</code>) étaient réservés au back-office authentifié. C&#39;est un changement de nature : n&#39;importe qui sur Internet peut désormais créer des lignes en base.</p><p>Le corpus pose une règle sans exception : <em>captcha sur tous les formulaires publics</em>. La question à trancher n&#39;est donc pas « faut-il un captcha » mais <strong>« que fait l&#39;API quand aucun fournisseur de captcha n&#39;est configuré ? »</strong> — et cette question se pose réellement, puisque le dépôt ne contenait aucune clé de configuration de captcha avant cet Epic, et qu&#39;une installation fraîchement déployée n&#39;en aura aucune.</p><p>Deux réponses sont possibles, et elles ne se valent pas :</p><ul><li><strong>Accepter la soumission sans protection</strong> (le formulaire fonctionne, il n&#39;est simplement pas protégé) ;</li><li><strong>Refuser la soumission</strong> (le formulaire ne fonctionne pas tant que l&#39;exploitant n&#39;a rien branché).</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Sans fournisseur de captcha branché, la soumission publique est refusée</strong> — <code>503</code>, avec un message qui nomme le réglage manquant (<code>CAPTCHA_PROVIDER</code>) et le point d&#39;extension à utiliser (<code>register_captcha_verifier</code>). Il n&#39;existe <strong>aucun</strong> mode de dégradation, aucun drapeau <code>CAPTCHA_OPTIONAL</code>, aucune valeur de configuration permettant d&#39;accepter sans vérifier.</p><p>Le raisonnement tient en une phrase : <strong>une dégradation silencieuse transformerait « sur tous les formulaires publics, sans exception » en « sur ceux des installations correctement configurées »</strong>, et personne ne saurait dans quelle catégorie se trouve la sienne. Les deux erreurs possibles n&#39;ont pas le même coût de découverte :</p><ul><li>le refus se remarque à la <strong>première recette</strong> — quelqu&#39;un remplit le formulaire, lit un message explicite, branche un fournisseur ;</li><li>l&#39;acceptation non protégée ne se remarque qu&#39;au <strong>premier dépôt automatisé de mille demandes</strong>, c&#39;est-à-dire une fois que le mal est fait, sur un service public, avec des données que le service devra trier.</li></ul><p>C&#39;est le même arbitrage que le CDC §8.3 impose à la visibilité (« pas de fuite par défaut ») et que l&#39;Epic E8 a retenu pour <code>data_leaves_infrastructure</code> (« se tromper du côté fermé se rattrape »).</p><p>Trois décisions accompagnent celle-ci :</p><p><strong>1. Aucun vérificateur n&#39;est livré avec le Core.</strong> Le Core ne connaît aucun client HTTP vers hCaptcha, Turnstile ou Altcha ; brancher un fournisseur est un acte d&#39;exploitation. C&#39;est la discipline d&#39;E8 pour l&#39;IA appliquée telle quelle — le Socle y pose un gestionnaire, et rien ne part tant qu&#39;un administrateur n&#39;a pas déclaré un fournisseur, un modèle et une politique (des adaptateurs réseau ont été branchés depuis, sans rien changer à cette règle) — et pour une raison au moins aussi forte : un service de captcha voit passer l&#39;adresse IP de <strong>chaque usager</strong> d&#39;un service public. Une installation neuve n&#39;appelle donc personne.</p><blockquote><p><em>Renvoi (28 septembre 2026) : cette décision n°1 est amendée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a>, décision n°2 — des vérificateurs sont livrés, inactifs sans réglage. Le texte ci-dessus est celui de la décision acceptée le 20 août 2026.</em></p></blockquote><p><strong>2. Le captcha est vérifié côté serveur, et rien de ce que dit le client n&#39;est cru.</strong> Aucun booléen <code>captcha_ok</code> n&#39;est lu. Seul compte un jeton opaque remis par le fournisseur et validé par un appel que le client ne contrôle pas. Corollaire de conception : <code>CaptchaFieldDef</code> (le champ du Field Engine) ne porte <strong>aucune valeur</strong> et ne protège rien à lui seul — la vérification est opposée par la route publique à toute soumission, que le schéma déclare le champ ou non. Faire dépendre la règle de la présence du champ l&#39;aurait fait dépendre de la vigilance de l&#39;auteur du formulaire.</p><p><strong>3. Le refus d&#39;exploitation précède le refus de jeton.</strong> Un exploitant qui n&#39;a rien branché lit « aucun fournisseur configuré » (503), jamais « jeton manquant » (400) — le second l&#39;enverrait chercher un défaut côté navigateur. L&#39;ordre est vérifié par un test.</p><h3 id="le-garde-fou--lapi-le-dit-avant-la-saisie" tabindex="-1">Le garde-fou : l&#39;API le dit avant la saisie <a class="header-anchor" href="#le-garde-fou--lapi-le-dit-avant-la-saisie" aria-label="Permalink to &quot;Le garde-fou : l&#39;API le dit avant la saisie {#le-garde-fou--lapi-le-dit-avant-la-saisie}&quot;">​</a></h3><p>Refuser après vingt champs remplis serait cruel et inutile. Le descripteur public d&#39;un formulaire (<code>GET /api/v1/public/forms/{clé}</code>) porte donc un objet <code>captcha</code> (<code>configured</code>, <code>provider</code>, <code>site_key</code>) : un front qui lit <code>configured: false</code> affiche « formulaire momentanément indisponible » au lieu de laisser saisir pour rien. C&#39;est la contrepartie honnête du refus, et c&#39;est ce qui fait passer cette ADR de « Accepté » à « Accepté avec garde-fou ».</p><h3 id="portée--toute-écriture-publique-y-compris-la-réponse-dans-un-fil-de-discussion" tabindex="-1">Portée : toute écriture publique, y compris la réponse dans un fil de discussion <a class="header-anchor" href="#portée--toute-écriture-publique-y-compris-la-réponse-dans-un-fil-de-discussion" aria-label="Permalink to &quot;Portée : toute écriture publique, y compris la réponse dans un fil de discussion {#portée--toute-écriture-publique-y-compris-la-réponse-dans-un-fil-de-discussion}&quot;">​</a></h3><p>La tentation existait d&#39;exempter le fil de discussion agent ↔ usager : l&#39;auteur y est déjà reconnu par son jeton de suivi, et redemander une épreuve à chaque message est pénible. <strong>L&#39;exemption a été écartée.</strong> La règle du corpus ne comporte pas d&#39;exception ; un formulaire de réponse ouvert sur Internet reste un formulaire ouvert sur Internet, et un jeton fuité par un partage de lien deviendrait un canal d&#39;injection automatisée. Le coût réel est faible avec les fournisseurs modernes (épreuve invisible) ; le coût de l&#39;exception aurait été de devoir la défendre à chaque nouveau chemin d&#39;écriture publique.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Accepter sans protection quand rien n&#39;est configuré</strong></td><td>Écartée : c&#39;est la dégradation silencieuse. Elle rend la règle du corpus invérifiable et déplace la découverte du défaut du jour du déploiement au jour de l&#39;attaque.</td></tr><tr><td><strong>Livrer un vérificateur par défaut appelant un service public gratuit</strong></td><td>Écartée : une installation neuve enverrait l&#39;IP de chaque usager d&#39;une collectivité vers un tiers que personne n&#39;a choisi, sans consentement ni mention au registre des traitements (E5). C&#39;est exactement ce que le CDC §14.8/§14.11 refuse pour l&#39;IA.</td></tr><tr><td><strong>Livrer un vérificateur « accepte tout » activable par <code>CAPTCHA_PROVIDER=insecure</code></strong></td><td>Écartée, bien qu&#39;explicite : une valeur de configuration nommée finit par se retrouver copiée d&#39;un <code>.env</code> de développement vers un <code>.env</code> de production. Le besoin réel (tester sans fournisseur) est couvert par <code>register_captcha_verifier()</code>, qui exige d&#39;écrire du code — donc de le faire exprès.</td></tr><tr><td><strong>Preuve de travail interne livrée par le Core, en repli</strong></td><td>Écartée pour cette version, mais c&#39;est la piste la plus sérieuse : elle supprimerait la dépendance à un tiers <em>et</em> le refus par défaut. Elle demande un vrai travail de conception (coût, accessibilité, résistance) qui n&#39;a pas sa place dans l&#39;Epic E11 — et l&#39;inventer à la hâte donnerait une protection dont personne ne pourrait dire ce qu&#39;elle vaut. Cf. actions liées.</td></tr><tr><td><strong>Rendre le captcha configurable par formulaire</strong></td><td>Écartée : <code>captcha: Literal[&quot;required&quot;]</code> rend l&#39;exception inexprimable dans la donnée stockée. Un formulaire « interne » qui voudrait s&#39;en dispenser n&#39;est pas un formulaire public — il relève de l&#39;ACL (E6), pas d&#39;un assouplissement du captcha.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La règle « captcha sur tous les formulaires publics » est vraie sur <strong>toute</strong> installation, sans condition de configuration.</li><li>Une installation neuve n&#39;appelle aucun service tiers et ne transmet aucune IP d&#39;usager.</li><li>Le défaut de configuration est bruyant, daté et localisé : un 503 nommant la variable manquante.</li><li>Le front peut prévenir l&#39;usager avant la saisie (garde-fou).</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un CMS fraîchement installé n&#39;accepte aucune soumission publique.</strong> C&#39;est le coût assumé, et il doit figurer en tête de la documentation d&#39;installation : sans cette mention, un intégrateur conclura à un bogue.</li><li>Les tests de recette doivent brancher un vérificateur eux-mêmes — ce qui est en réalité une propriété désirable (ils exercent le point d&#39;extension réel), mais rend la fixture obligatoire.</li><li>Le choix du fournisseur reste entier et hors du CMS : accessibilité (RGAA, CDC §12), souveraineté et coût sont à instruire par chaque collectivité, sans que le Core n&#39;oriente la décision.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Documentation d&#39;installation : mentionner en tête que <code>CAPTCHA_PROVIDER</code> conditionne toute soumission publique. → fait le 14 septembre 2026, <code>docs/notice-utilisateur.md</code> §« Exploitation » et <code>apps/api/.env.example</code>.</li><li>[x] Étudier une preuve de travail interne livrée par le Core (type Altcha auto-hébergé) comme repli sans tiers — coût, accessibilité et résistance à instruire avant de décider ; remplacerait partiellement cette ADR. → <strong>instruit et livré</strong> le 14 septembre 2026 (ADR-0027) : Altcha est livré au même titre que Turnstile et hCaptcha, émis et vérifié par ce serveur (<code>GET /api/v1/public/captcha/challenge</code>, anti-rejeu en base), sans aucun tiers contacté ni aucune IP transmise. Il ne « remplace partiellement » pas cette ADR : il ne supprime <strong>pas</strong> le refus par défaut — un vérificateur livré n&#39;est pas un vérificateur configuré, et une installation neuve refuse toujours les soumissions publiques.</li><li>[x] Étendre la règle à l&#39;inscription spontanée d&#39;un usager, seule écriture publique qui y échappait (audit du 15/09) → fait le 18 septembre 2026 : <code>POST /api/v1/account/register</code> exige le captcha et répond 503 tant qu&#39;aucun n&#39;est configuré, comme un formulaire. Les comptes créés par le back-office ne sont pas concernés.</li><li>[ ] Epic RGAA / accessibilité : vérifier que le fournisseur retenu par une collectivité propose une alternative accessible, le captcha étant un point de rupture classique du RGAA. <strong>Reste ouvert</strong>, et Altcha ne le referme pas : une preuve de travail est invisible pour l&#39;usager, mais elle s&#39;exécute dans son navigateur — un appareil ancien la paie en secondes d&#39;attente, ce qui est une barrière d&#39;un autre genre (<code>ALTCHA_MAX_NUMBER</code> en règle le coût).</li></ul>',30)])])}const m=t(a,[["render",s]]);export{f as __pageData,m as default};
